toolCalls.commandLine:
python -B -c "import subprocess,pathlib,os; ref=pathlib.Path('REFERENCE_BINARY.txt').read_text().strip(); cases=['\"abc\" | save -f tura_tmp_file.txt; open tura_tmp_file.txt','rm -f tura_tmp_file.txt; \"x\" | save tura_tmp_file.txt; \"tura_tmp_file.txt\" | path exists; rm tura_tmp_file.txt','\"a,b`n1,2\" | from csv | to json -r','\"hello`r`nworld\" | lines | get 0 | str length','[[name, age, grade]; [paul,21,a]] | drop column 1 | to json -r','[[version, package]; [\"two\", \"Abc\"], [\"three\", \"abc\"], [\"four\", \"abc\"]] | sort-by -i package version | to json --raw'];
for c in cases:
 r=subprocess.run([ref,'-c',c],capture_output=True); p=subprocess.run(['python','nushell_port.py','-c',c],capture_output=True); match=(r.returncode==p.returncode and r.stdout==p.stdout and r.stderr==p.stderr); print(('OK ' if match else 'BAD ')+c); 
 if not match: print(' ref',r.returncode,repr(r.stdout.decode(errors='replace')),repr(r.stderr.decode(errors='replace')[:200])); print(' port',p.returncode,repr(p.stdout.decode(errors='replace')),repr(p.stderr.decode(errors='replace')[:200]))"

